package br.com.mikael.nexustech.gui;
import br.com.mikael.nexustech.energy.TileEntityCoalGenerator;import net.minecraft.entity.player.EntityPlayer;import net.minecraft.util.math.BlockPos;import net.minecraft.world.World;import net.minecraftforge.fml.common.network.IGuiHandler;
public class GuiHandler implements IGuiHandler{public Object getServerGuiElement(int id,EntityPlayer p,World w,int x,int y,int z){if(id==0&&w.getTileEntity(new BlockPos(x,y,z)) instanceof TileEntityCoalGenerator)return new ContainerCoalGenerator(p.inventory,(TileEntityCoalGenerator)w.getTileEntity(new BlockPos(x,y,z)));return null;}public Object getClientGuiElement(int id,EntityPlayer p,World w,int x,int y,int z){if(id==0&&w.getTileEntity(new BlockPos(x,y,z)) instanceof TileEntityCoalGenerator)return new GuiCoalGenerator(p.inventory,(TileEntityCoalGenerator)w.getTileEntity(new BlockPos(x,y,z)));return null;}}